-- Devices, silent-push queue, tombstone purge and scheduled jobs.

-- ---------------------------------------------------------------------------
-- devices (per user, not synced)
-- ---------------------------------------------------------------------------
-- id is generated by the app once per installation and kept in the Keychain.
create table public.devices (
  id uuid primary key,
  user_id uuid not null default auth.uid() references auth.users (id) on delete cascade,
  apns_token text not null unique,
  platform public.device_platform not null,
  apns_env public.apns_environment not null,
  app_version text,
  last_seen_at timestamptz not null default now(),
  disabled_at timestamptz,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);
create index devices_user_id_idx on public.devices (user_id);
create trigger devices_touch before update on public.devices
  for each row execute function private.touch_updated_at();

alter table public.devices enable row level security;
create policy devices_select on public.devices for select to authenticated
  using (user_id = (select auth.uid()));
create policy devices_insert on public.devices for insert to authenticated
  with check (user_id = (select auth.uid()));
create policy devices_update on public.devices for update to authenticated
  using (user_id = (select auth.uid())) with check (user_id = (select auth.uid()));
create policy devices_delete on public.devices for delete to authenticated
  using (user_id = (select auth.uid()));
revoke all on public.devices from anon;
grant select, insert, update, delete on public.devices to authenticated;

-- Registers or refreshes the caller's device. SECURITY DEFINER because an APNs token (or an
-- installation id) may move between accounts on the same phone: the previous row is replaced.
create or replace function public.register_device(
  p_id uuid,
  p_apns_token text,
  p_platform public.device_platform,
  p_apns_env public.apns_environment,
  p_app_version text default null
)
returns public.devices
language plpgsql
volatile
security definer
set search_path = ''
as $$
declare
  v_uid uuid := auth.uid();
  v_row public.devices;
begin
  if v_uid is null then
    raise exception 'not authenticated' using errcode = 'insufficient_privilege';
  end if;
  if p_id is null or coalesce(btrim(p_apns_token), '') = '' then
    raise exception 'id and apns_token are required' using errcode = 'invalid_parameter_value';
  end if;

  delete from public.devices where apns_token = p_apns_token and id <> p_id;

  insert into public.devices (id, user_id, apns_token, platform, apns_env, app_version, last_seen_at, disabled_at)
  values (p_id, v_uid, p_apns_token, p_platform, p_apns_env, p_app_version, now(), null)
  on conflict (id) do update set
    user_id = excluded.user_id,
    apns_token = excluded.apns_token,
    platform = excluded.platform,
    apns_env = excluded.apns_env,
    app_version = excluded.app_version,
    last_seen_at = now(),
    disabled_at = null
  returning * into v_row;
  return v_row;
end;
$$;

-- Removes one of the caller's devices (logout). Returns whether a row was deleted.
create or replace function public.unregister_device(p_id uuid)
returns boolean
language plpgsql
security invoker
set search_path = ''
as $$
begin
  delete from public.devices where id = p_id and user_id = (select auth.uid());
  return found;
end;
$$;

-- ---------------------------------------------------------------------------
-- push_queue (internal)
-- ---------------------------------------------------------------------------
-- One row per (household, transaction) that changed synced data. payload:
-- { reasons: ['shopping' | 'planning' | 'recipes' | 'catalog'], cursor: <max server_seq> }.
create table public.push_queue (
  id bigint generated always as identity primary key,
  household_id uuid not null references public.households (id) on delete cascade,
  actor_user_id uuid,
  actor_device_id uuid,
  kind text not null default 'sync',
  payload jsonb not null default '{}'::jsonb,
  txid bigint not null default (pg_current_xact_id()::text::bigint),
  created_at timestamptz not null default now(),
  sent_at timestamptz
);
create unique index push_queue_household_txid_idx on public.push_queue (household_id, txid);
create index push_queue_pending_idx on public.push_queue (id) where sent_at is null;
create index push_queue_household_id_idx on public.push_queue (household_id);

alter table public.push_queue enable row level security;
-- No policies: only SECURITY DEFINER functions and the secret key touch this table.
revoke all on public.push_queue from anon, authenticated;

create or replace function private.enqueue_sync_push()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
begin
  insert into public.push_queue (household_id, actor_user_id, actor_device_id, kind, payload)
  values (
    new.household_id,
    auth.uid(),
    nullif(current_setting('koda.device_id', true), '')::uuid,
    'sync',
    jsonb_build_object('reasons', jsonb_build_array(tg_argv[0]), 'cursor', new.server_seq)
  )
  on conflict (household_id, txid) do update set
    payload = jsonb_build_object(
      'reasons', (
        select jsonb_agg(distinct r.value)
        from jsonb_array_elements_text(
          coalesce(public.push_queue.payload -> 'reasons', '[]'::jsonb) || (excluded.payload -> 'reasons')
        ) r
      ),
      'cursor', greatest(
        (public.push_queue.payload ->> 'cursor')::bigint,
        (excluded.payload ->> 'cursor')::bigint
      )
    ),
    actor_user_id = coalesce(public.push_queue.actor_user_id, excluded.actor_user_id),
    actor_device_id = coalesce(public.push_queue.actor_device_id, excluded.actor_device_id);
  return null;
end;
$$;

do $$
declare
  r record;
begin
  for r in
    select * from (values
      ('stores', 'catalog'), ('products', 'catalog'), ('product_stores', 'catalog'),
      ('recipes', 'recipes'), ('recipe_ingredients', 'recipes'), ('recipe_components', 'recipes'),
      ('meal_plan_drafts', 'planning'), ('meal_plan_entries', 'planning'), ('consumptions', 'planning'),
      ('shopping_entries', 'shopping'), ('shopping_entry_items', 'shopping')
    ) as v (tbl, reason)
  loop
    execute format(
      'create trigger t90_enqueue_push after insert or update on public.%I for each row execute function private.enqueue_sync_push(%L)',
      r.tbl, r.reason
    );
  end loop;
end;
$$;

-- Claims pending queue rows (marks them sent) for the push function. Service role only.
create or replace function public.claim_push_batch(p_limit integer default 500)
returns setof public.push_queue
language sql
volatile
security definer
set search_path = ''
as $$
  update public.push_queue q
  set sent_at = now()
  where q.id in (
    select p.id from public.push_queue p
    where p.sent_at is null
    order by p.id
    limit greatest(1, least(coalesce(p_limit, 500), 5000))
    for update skip locked
  )
  returning q.*;
$$;

-- Live devices of every member of the given households. Service role only.
create or replace function public.push_devices_for_households(p_household_ids uuid[])
returns table (
  household_id uuid,
  device_id uuid,
  user_id uuid,
  apns_token text,
  apns_env public.apns_environment,
  platform public.device_platform
)
language sql
stable
security definer
set search_path = ''
as $$
  select hm.household_id, d.id, d.user_id, d.apns_token, d.apns_env, d.platform
  from public.household_members hm
  join public.devices d on d.user_id = hm.user_id and d.disabled_at is null
  where hm.household_id = any (p_household_ids);
$$;

-- ---------------------------------------------------------------------------
-- Tombstone purge (keepalive)
-- ---------------------------------------------------------------------------
-- Hard-deletes tombstones older than p_older_than (children first), records the purge
-- watermark used by pull_changes.reset_required, trims old push_queue rows and touches the
-- keepalive timestamp. Service role only.
create or replace function public.purge_tombstones(p_older_than interval default interval '30 days')
returns jsonb
language plpgsql
volatile
security definer
set search_path = ''
as $$
declare
  v_cutoff timestamptz := now() - p_older_than;
  v_table text;
  v_count bigint;
  v_max bigint;
  v_watermark bigint := 0;
  v_counts jsonb := '{}'::jsonb;
  v_queue bigint;
begin
  foreach v_table in array array[
    'shopping_entry_items', 'shopping_entries', 'consumptions', 'meal_plan_entries', 'meal_plan_drafts',
    'recipe_components', 'recipe_ingredients', 'recipes', 'product_stores', 'products', 'stores'
  ] loop
    execute format(
      'with d as (delete from public.%I where deleted_at < $1 returning server_seq) select count(*), max(server_seq) from d',
      v_table
    ) into v_count, v_max using v_cutoff;
    v_counts := v_counts || jsonb_build_object(v_table, v_count);
    v_watermark := greatest(v_watermark, coalesce(v_max, 0));
  end loop;

  with d as (delete from public.push_queue where sent_at < now() - interval '7 days' returning 1)
  select count(*) into v_queue from d;

  update private.sync_state
  set purge_watermark = greatest(purge_watermark, v_watermark),
      last_purge_at = now(),
      keepalive_at = now()
  where id;

  return jsonb_build_object(
    'purged', v_counts,
    'push_queue_trimmed', v_queue,
    'watermark', public.sync_purge_watermark(),
    'at', now()
  );
end;
$$;

revoke execute on function
  public.claim_push_batch(integer),
  public.push_devices_for_households(uuid[]),
  public.purge_tombstones(interval)
from public, anon, authenticated;
grant execute on function
  public.claim_push_batch(integer),
  public.push_devices_for_households(uuid[]),
  public.purge_tombstones(interval)
to service_role;

revoke execute on function public.register_device(uuid, text, public.device_platform, public.apns_environment, text),
  public.unregister_device(uuid)
from public, anon;
grant execute on function public.register_device(uuid, text, public.device_platform, public.apns_environment, text),
  public.unregister_device(uuid)
to authenticated;

-- ---------------------------------------------------------------------------
-- Scheduled jobs (pg_cron + pg_net)
-- ---------------------------------------------------------------------------
-- Configuration lives in Supabase Vault (never in git). Without these secrets the jobs are no-ops:
--   koda_functions_url     https://<project-ref>.supabase.co/functions/v1
--   koda_push_secret       same value as the PUSH_INTERNAL_SECRET function secret
--   koda_keepalive_secret  same value as the KEEPALIVE_SECRET function secret
-- See README.md ("Scheduled jobs").
create or replace function private.vault_secret(p_name text)
returns text
language sql
stable
security definer
set search_path = ''
as $$
  select s.decrypted_secret from vault.decrypted_secrets s where s.name = p_name limit 1;
$$;

create or replace function private.invoke_internal_function(p_function text, p_secret_name text)
returns bigint
language plpgsql
volatile
security definer
set search_path = ''
as $$
declare
  v_base text := private.vault_secret('koda_functions_url');
  v_secret text := private.vault_secret(p_secret_name);
begin
  if v_base is null or v_secret is null then
    return null;
  end if;
  return net.http_post(
    url := rtrim(v_base, '/') || '/' || p_function,
    body := '{}'::jsonb,
    headers := jsonb_build_object('Content-Type', 'application/json', 'x-koda-secret', v_secret),
    timeout_milliseconds := 15000
  );
end;
$$;

-- Calls the push function only when there is something to send (saves invocations).
create or replace function private.kick_push()
returns bigint
language plpgsql
volatile
security definer
set search_path = ''
as $$
begin
  if not exists (select 1 from public.push_queue where sent_at is null) then
    return null;
  end if;
  return private.invoke_internal_function('push', 'koda_push_secret');
end;
$$;

revoke execute on all functions in schema private from public, anon, authenticated;

select cron.schedule('koda-push', '* * * * *', $$select private.kick_push()$$);
select cron.schedule('koda-keepalive', '17 4 * * *', $$select private.invoke_internal_function('keepalive', 'koda_keepalive_secret')$$);
